1	import { NextResponse } from "next/server";
2	import { prisma } from "@/lib/db";
3	
4	// Force dynamic so Next.js does not attempt static page-data collection
5	// at build time (which would fail without a DATABASE_URL in CI/Docker).
6	export const dynamic = "force-dynamic";
7	
8	export async function GET() {
9	  try {
10	    await prisma.$queryRaw`SELECT 1`;
11	    return NextResponse.json({ status: "ok" });
12	  } catch {
13	    return NextResponse.json(
14	      { status: "error", message: "database unavailable" },
15	      { status: 503 }
16	    );
17	  }
18	}
