1	import { PrismaClient } from "@/generated/prisma/client";
2	import { PrismaPg } from "@prisma/adapter-pg";
3	
4	const globalForPrisma = globalThis as unknown as {
5	  prisma: PrismaClient | undefined;
6	};
7	
8	function getDatabaseUrl(): string {
9	  const url = process.env.DATABASE_URL;
10	  if (!url || url.trim() === "") {
11	    throw new Error("DATABASE_URL environment variable is not set or is empty.");
12	  }
13	  return url;
14	}
15	
16	const DEFAULT_PG_POOL_MAX = 20;
17	const DEFAULT_PG_POOL_IDLE_TIMEOUT_MS = 30000;
18	const DEFAULT_PG_POOL_CONNECTION_TIMEOUT_MS = 5000;
19	
20	const _pgPoolMax = Number.parseInt(process.env.PG_POOL_MAX ?? "", 10);
21	const PG_POOL_MAX = Number.isNaN(_pgPoolMax) ? DEFAULT_PG_POOL_MAX : _pgPoolMax;
22	
23	const _pgPoolIdleTimeout = Number.parseInt(process.env.PG_POOL_IDLE_TIMEOUT_MS ?? "", 10);
24	const PG_POOL_IDLE_TIMEOUT_MS = Number.isNaN(_pgPoolIdleTimeout) ? DEFAULT_PG_POOL_IDLE_TIMEOUT_MS : _pgPoolIdleTimeout;
25	
26	const _pgPoolConnectionTimeout = Number.parseInt(process.env.PG_POOL_CONNECTION_TIMEOUT_MS ?? "", 10);
27	const PG_POOL_CONNECTION_TIMEOUT_MS = Number.isNaN(_pgPoolConnectionTimeout) ? DEFAULT_PG_POOL_CONNECTION_TIMEOUT_MS : _pgPoolConnectionTimeout;
28	
29	function createPrismaClient() {
30	  const adapter = new PrismaPg({
31	    connectionString: getDatabaseUrl(),
32	    max: PG_POOL_MAX,
33	    idleTimeoutMillis: PG_POOL_IDLE_TIMEOUT_MS,
34	    connectionTimeoutMillis: PG_POOL_CONNECTION_TIMEOUT_MS,
35	  });
36	  return new PrismaClient({
37	    adapter,
38	    log:
39	      process.env.NODE_ENV === "development"
40	        ? ["query", "warn"]
41	        : ["error"],
42	  });
43	}
44	
45	export const prisma = globalForPrisma.prisma ?? createPrismaClient();
46	
47	if (process.env.NODE_ENV !== "production") globalForPrisma.prisma = prisma;
